/**
 * Playable maps. Geometry and adjacency are generated by scripts/build-map.mjs into ./generated/*.json
 * (from real-world geography, or from hand-authored landmasses for the fantasy board); this module wraps
 * them with lookups.
 */
import classicJson from './generated/classic.json' with { type: 'json' };
import worldJson from './generated/world.json' with { type: 'json' };
import worldLargeJson from './generated/world_large.json' with { type: 'json' };
import europeJson from './generated/europe.json' with { type: 'json' };
import europeAdvancedJson from './generated/europe_advanced.json' with { type: 'json' };
import europeClassicJson from './generated/europe_classic.json' with { type: 'json' };
import greaterEuropeJson from './generated/greater_europe.json' with { type: 'json' };
import usaJson from './generated/usa.json' with { type: 'json' };
import asiaJson from './generated/asia.json' with { type: 'json' };
import fantasyJson from './generated/fantasy.json' with { type: 'json' };
import skirmishJson from './generated/skirmish.json' with { type: 'json' };
import nineRealmsJson from './generated/nine_realms.json' with { type: 'json' };
import { RuleError } from './types.js';

export type MapId = 'classic' | 'world' | 'world_large' | 'europe' | 'europe_advanced' | 'greater_europe' | 'europe_classic' | 'usa' | 'asia' | 'fantasy' | 'skirmish' | 'nine_realms';
/**
 * Maps offered for new games (option enum, MCP schema, lobby list, GET /maps). Every map in MAPS that is not
 * listed here is a legacy board: it stays loadable so saved games on it keep working, but cannot be picked.
 * A board's id is never reused for different territories; a reworked board gets a new id.
 */
export const MAP_IDS: MapId[] = ['classic', 'world', 'world_large', 'europe', 'greater_europe', 'europe_classic', 'usa', 'asia', 'fantasy', 'skirmish', 'nine_realms'];
/** Boards kept only for saved games: 'europe_advanced' (Europe (legacy, 99), superseded by greater_europe). */
export const LEGACY_MAP_IDS: MapId[] = ['europe_advanced'];

export interface TerritoryDef {
  id: string;
  name: string;
  continent: string;
  /** Label / army badge anchor in the map's viewBox. */
  x: number;
  y: number;
  /** SVG path data for the territory shape. */
  path: string;
  /** Bounding box of the shape: [x, y, width, height]. */
  bbox: [number, number, number, number];
}

export interface ContinentDef {
  id: string;
  name: string;
  bonus: number;
  territories: string[];
  /** SVG path data for the continent outline (union of its territories). */
  outline: string;
  /** Optional label position in the viewBox. */
  labelX?: number;
  labelY?: number;
}

export interface SeaLink {
  a: string;
  b: string;
  /** Link that wraps around the map edge (Alaska <-> Kamchatka). */
  wrap: boolean;
}

export interface MapDef {
  id: MapId;
  name: string;
  maxPlayers: number;
  viewBox: [number, number];
  territories: TerritoryDef[];
  territoryIds: string[];
  territoryById: Record<string, TerritoryDef>;
  continents: ContinentDef[];
  continentById: Record<string, ContinentDef>;
  adjacency: Record<string, string[]>;
  edges: [string, string][];
  /** Adjacent pairs that do not touch on the map and are drawn as link lines. */
  seaLinks: SeaLink[];
  isAdjacent(a: string, b: string): boolean;
  isTerritory(id: string): boolean;
  /** Starting armies per player for a game with `players` players. */
  startingArmies(players: number): number;
}

interface RawMap {
  id: string;
  name: string;
  maxPlayers: number;
  viewBox: number[];
  territories: TerritoryDef[];
  continents: ContinentDef[];
  edges: string[][];
  seaLinks: SeaLink[];
}

/**
 * How many armies each player starts with, per map. Change a map's starting armies here.
 * - `table`: fixed numbers by player count.
 * - `classicScaled`: the classic board-game numbers (2: 40, 3: 35, 4: 30, 5: 25, 6: 20 on 42 territories)
 *   scaled by this map's size; above 6 players everyone gets an equal share of the 6-player total
 *   (120 armies per 42 territories). Never fewer than 1.5 armies per territory a player is dealt.
 * - `perTerritory`: about that many armies per territory shared out, clamped to [min, max] each.
 */
export type StartingArmiesRule = { table: Record<number, number> } | { classicScaled: true } | { perTerritory: number; min: number; max: number };

/** Classic Hasbro starting armies on the 42-territory board. */
export const CLASSIC_STARTING_ARMIES: Record<number, number> = { 2: 40, 3: 35, 4: 30, 5: 25, 6: 20 };

export const STARTING_ARMIES: Record<MapId, StartingArmiesRule> = {
  classic: { table: CLASSIC_STARTING_ARMIES },
  world: { classicScaled: true },
  world_large: { classicScaled: true },
  europe: { classicScaled: true },
  europe_advanced: { classicScaled: true },
  greater_europe: { classicScaled: true },
  europe_classic: { classicScaled: true },
  usa: { classicScaled: true },
  asia: { classicScaled: true },
  fantasy: { classicScaled: true },
  skirmish: { classicScaled: true },
  nine_realms: { classicScaled: true },
};

/** Classic numbers scaled to a map with `territoryCount` territories (see StartingArmiesRule). */
export function classicScaledArmies(territoryCount: number, players: number): number {
  const scale = territoryCount / 42;
  const scaled = players <= 6 ? Math.round(CLASSIC_STARTING_ARMIES[players] * scale) : Math.round((120 * scale) / players);
  // Two-player games deal a third of the map to the Neutral.
  const dealt = Math.ceil(territoryCount / (players === 2 ? 3 : players));
  return Math.max(scaled, Math.ceil(dealt * 1.5));
}

function startingArmiesFor(rule: StartingArmiesRule, territoryCount: number, maxPlayers: number) {
  return (players: number): number => {
    if (!Number.isInteger(players) || players < 2 || players > maxPlayers) throw new RuleError(`This map supports 2-${maxPlayers} players`);
    if ('table' in rule) {
      const n = rule.table[players];
      if (!n) throw new RuleError(`No starting armies defined for ${players} players on this map`);
      return n;
    }
    if ('classicScaled' in rule) return classicScaledArmies(territoryCount, players);
    return Math.max(rule.min, Math.min(rule.max, Math.round((territoryCount * rule.perTerritory) / players)));
  };
}

function wrap(raw: RawMap): MapDef {
  const territoryIds = raw.territories.map((t) => t.id);
  const territoryById = Object.fromEntries(raw.territories.map((t) => [t.id, t]));
  const adjacency: Record<string, string[]> = Object.fromEntries(territoryIds.map((t) => [t, [] as string[]]));
  const edges = raw.edges as [string, string][];
  for (const [a, b] of edges) {
    if (!adjacency[a] || !adjacency[b]) throw new Error(`Map ${raw.id}: bad edge ${a}-${b}`);
    adjacency[a].push(b);
    adjacency[b].push(a);
  }
  const id = raw.id as MapId;
  return {
    id,
    name: raw.name,
    maxPlayers: raw.maxPlayers,
    viewBox: [raw.viewBox[0], raw.viewBox[1]],
    territories: raw.territories,
    territoryIds,
    territoryById,
    continents: raw.continents,
    continentById: Object.fromEntries(raw.continents.map((c) => [c.id, c])),
    adjacency,
    edges,
    seaLinks: raw.seaLinks,
    isAdjacent: (a, b) => adjacency[a]?.includes(b) ?? false,
    isTerritory: (t) => t in territoryById,
    startingArmies: startingArmiesFor(STARTING_ARMIES[id], territoryIds.length, raw.maxPlayers),
  };
}

export const MAPS: Record<MapId, MapDef> = {
  classic: wrap(classicJson as RawMap),
  world: wrap(worldJson as RawMap),
  world_large: wrap(worldLargeJson as RawMap),
  europe: wrap(europeJson as RawMap),
  europe_advanced: wrap(europeAdvancedJson as RawMap),
  greater_europe: wrap(greaterEuropeJson as RawMap),
  europe_classic: wrap(europeClassicJson as RawMap),
  usa: wrap(usaJson as RawMap),
  asia: wrap(asiaJson as RawMap),
  fantasy: wrap(fantasyJson as RawMap),
  skirmish: wrap(skirmishJson as RawMap),
  nine_realms: wrap(nineRealmsJson as RawMap),
};

export function getMap(id: string | undefined): MapDef {
  const m = MAPS[(id ?? 'classic') as MapId];
  if (!m) throw new RuleError(`Unknown map "${id}"`);
  return m;
}

export function isMapId(id: unknown): id is MapId {
  return typeof id === 'string' && id in MAPS;
}

// ---- Backward-compatible aliases for the classic map ----
export const CLASSIC = MAPS.classic;
export const TERRITORIES = CLASSIC.territories;
export const TERRITORY_IDS = CLASSIC.territoryIds;
export const TERRITORY_BY_ID = CLASSIC.territoryById;
export const CONTINENTS = CLASSIC.continents;
export const CONTINENT_BY_ID = CLASSIC.continentById;
export const ADJACENCY = CLASSIC.adjacency;
export const EDGE_LIST: ReadonlyArray<readonly [string, string]> = CLASSIC.edges;
export const isAdjacent = CLASSIC.isAdjacent;
export const isTerritory = CLASSIC.isTerritory;
